/* ========== TIMELINE ========== */
.timeline { display: flex; flex-direction: column; gap: 32px; }
.timeline-item { display: flex; gap: 24px; align-items: flex-start; }
.timeline-marker {
  min-width: 80px; text-align: center;
}
.timeline-marker .time-val {
  font-size: 1.5rem; font-weight: 800; color: var(--accent-blue);
}
.timeline-marker .time-unit {
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
