@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

:root {
  --primary-navy: #0D1B2A;
  --secondary-navy: #1B2838;
  --dark-gray: #3C424B;
  --accent-blue: #00B4D8;
  --deep-blue: #0077B6;
  --accent-green: #6CC24A;
  --brand-navy: #15295A;
  --text-white: #FFFFFF;
  --text-light: #B8C4D0;
  --text-muted: #8899AA;
  --border-color: rgba(255,255,255,0.08);
  --card-bg: rgba(27, 40, 56, 0.6);
  --card-bg-solid: #1B2838;
  --gradient-hero: linear-gradient(135deg, #0D1B2A 0%, #15295A 50%, #0D1B2A 100%);
  --transition: all 0.3s ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--primary-navy);
  color: var(--text-light);
  line-height: 1.6;
  overflow-x: hidden;
}

a { color: var(--accent-blue); text-decoration: none; transition: var(--transition); }
a:hover { color: var(--accent-green); }

img { max-width: 100%; height: auto; }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* ========== HEADER / NAV ========== */
.header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 1000;
  background: rgba(13, 27, 42, 0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px;
  height: 72px;
}

.header-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  height: 100%;
}

.logo {
  font-size: 1.35rem; font-weight: 700;
  color: var(--text-white); letter-spacing: -0.02em;
  display: flex; align-items: center; gap: 10px;
}

.logo-icon {
  width: 36px; height: 36px; border-radius: 8px;
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; font-size: 0.9rem; color: #fff;
}

.nav { display: flex; align-items: center; gap: 8px; }

.nav-link {
  color: var(--text-light); font-size: 0.9rem; font-weight: 500;
  padding: 8px 16px; border-radius: 6px;
  transition: var(--transition); position: relative;
}
.nav-link:hover { color: var(--text-white); background: rgba(255,255,255,0.05); }
.nav-link.active { color: var(--accent-blue); }

.nav-dropdown { position: relative; }
.nav-dropdown-toggle { cursor: pointer; display: flex; align-items: center; gap: 4px; }
.nav-dropdown-toggle::after {
  content: ''; width: 0; height: 0;
  border-left: 4px solid transparent; border-right: 4px solid transparent;
  border-top: 4px solid currentColor;
  transition: transform 0.2s ease;
}
.nav-dropdown:hover .nav-dropdown-toggle::after { transform: rotate(180deg); }

.nav-dropdown-menu {
  position: absolute; top: calc(100% + 8px); left: 0;
  background: var(--secondary-navy); border: 1px solid var(--border-color);
  border-radius: 8px; padding: 8px; min-width: 200px;
  opacity: 0; visibility: hidden; transform: translateY(-8px);
  transition: var(--transition); box-shadow: 0 16px 48px rgba(0,0,0,0.3);
}
.nav-dropdown:hover .nav-dropdown-menu { opacity: 1; visibility: visible; transform: translateY(0); }

.nav-dropdown-menu a {
  display: block; padding: 10px 14px; border-radius: 6px;
  color: var(--text-light); font-size: 0.875rem; font-weight: 500;
}
.nav-dropdown-menu a:hover { background: rgba(0,180,216,0.1); color: var(--accent-blue); }

.btn-demo {
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  color: #fff; padding: 10px 24px; border-radius: 8px;
  font-size: 0.9rem; font-weight: 600; border: none; cursor: pointer;
  transition: var(--transition); display: inline-flex; align-items: center; gap: 8px;
}
.btn-demo:hover { transform: translateY(-1px); box-shadow: 0 8px 24px rgba(0,180,216,0.3); color: #fff; }

.mobile-menu-toggle {
  display: none; background: none; border: none;
  color: var(--text-white); font-size: 1.5rem; cursor: pointer;
  padding: 8px;
}

/* ========== HERO ========== */
.hero {
  min-height: 85vh; display: flex; align-items: center;
  background: var(--gradient-hero); position: relative;
  padding-top: 72px; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 70% 20%, rgba(0,180,216,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 30% 80%, rgba(0,119,182,0.06) 0%, transparent 50%);
}
.hero-grid {
  position: absolute; inset: 0; opacity: 0.03;
  background-image: linear-gradient(rgba(255,255,255,0.3) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.3) 1px, transparent 1px);
  background-size: 60px 60px;
}
.hero .container { position: relative; z-index: 1; }
.hero-content { max-width: 720px; }
.hero-label {
  display: inline-block; font-size: 0.75rem; font-weight: 600;
  letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--accent-blue); margin-bottom: 16px;
  padding: 6px 14px; border-radius: 20px;
  background: rgba(0,180,216,0.1); border: 1px solid rgba(0,180,216,0.2);
}
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.5rem); font-weight: 800;
  color: var(--text-white); line-height: 1.1; margin-bottom: 20px;
  letter-spacing: -0.03em;
}
.hero h1 span { color: var(--accent-blue); }
.hero p {
  font-size: 1.15rem; color: var(--text-light); max-width: 560px;
  margin-bottom: 32px; line-height: 1.7;
}
.hero-ctas { display: flex; gap: 16px; flex-wrap: wrap; }
.btn-primary {
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  color: #fff; padding: 14px 32px; border-radius: 8px;
  font-size: 0.95rem; font-weight: 600; border: none; cursor: pointer;
  transition: var(--transition);
}
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(0,180,216,0.3); color: #fff; }
.btn-secondary {
  background: transparent; color: var(--text-white);
  padding: 14px 32px; border-radius: 8px; font-size: 0.95rem;
  font-weight: 600; border: 1px solid rgba(255,255,255,0.2); cursor: pointer;
  transition: var(--transition);
}
.btn-secondary:hover { border-color: var(--accent-blue); color: var(--accent-blue); background: rgba(0,180,216,0.05); }

.hero-sm { min-height: 50vh; }
.hero-sm h1 { font-size: clamp(1.8rem, 4vw, 2.8rem); }

/* ========== SECTIONS ========== */
section { padding: 96px 0; }
.section-label {
  font-size: 0.75rem; font-weight: 600; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--accent-blue); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.5rem); font-weight: 700;
  color: var(--text-white); margin-bottom: 16px; letter-spacing: -0.02em;
}
.section-desc {
  font-size: 1.05rem; color: var(--text-light); max-width: 640px;
  line-height: 1.7; margin-bottom: 48px;
}
.section-dark { background: var(--primary-navy); }
.section-darker { background: #0A1525; }
.section-alt { background: var(--secondary-navy); }

/* ========== CARDS ========== */
.card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: 12px; padding: 32px; transition: var(--transition);
}
.card:hover { border-color: rgba(0,180,216,0.3); transform: translateY(-4px);
  box-shadow: 0 16px 48px rgba(0,0,0,0.2); }
.card-icon {
  width: 48px; height: 48px; border-radius: 10px;
  background: linear-gradient(135deg, rgba(0,180,216,0.15), rgba(0,119,182,0.15));
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px; font-size: 1.4rem; color: var(--accent-blue);
}
.card h3 { font-size: 1.1rem; font-weight: 600; color: var(--text-white); margin-bottom: 10px; }
.card p { font-size: 0.9rem; color: var(--text-muted); line-height: 1.6; }

.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.grid-6 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }

/* ========== FEATURED BANNER ========== */
.featured-banner {
  background: linear-gradient(135deg, var(--brand-navy), var(--deep-blue));
  padding: 48px; border-radius: 16px; margin-top: -48px;
  position: relative; z-index: 2;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 24px;
  border: 1px solid rgba(0,180,216,0.2);
}
.featured-banner h3 { color: var(--text-white); font-size: 1.5rem; font-weight: 700; }
.featured-banner p { color: var(--text-light); margin-top: 8px; font-size: 1rem; }
.featured-banner .btn-primary { background: var(--accent-green); }
.featured-banner .btn-primary:hover { box-shadow: 0 12px 32px rgba(108,194,74,0.3); }

/* ========== TABS ========== */
.tabs { margin-bottom: 40px; }
.tab-nav {
  display: flex; gap: 4px; flex-wrap: wrap;
  border-bottom: 1px solid var(--border-color); padding-bottom: 0;
}
.tab-btn {
  padding: 12px 24px; font-size: 0.9rem; font-weight: 500;
  color: var(--text-muted); background: transparent; border: none;
  cursor: pointer; transition: var(--transition);
  border-bottom: 2px solid transparent; position: relative;
  font-family: inherit;
}
.tab-btn:hover { color: var(--text-light); }
.tab-btn.active { color: var(--accent-blue); border-bottom-color: var(--accent-blue); }

.tab-panel { display: none; animation: fadeIn 0.3s ease; }
.tab-panel.active { display: block; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ========== ACCORDION ========== */
.accordion { display: flex; flex-direction: column; gap: 8px; }
.accordion-item {
  border: 1px solid var(--border-color); border-radius: 10px;
  overflow: hidden; transition: var(--transition);
}
.accordion-item:hover { border-color: rgba(0,180,216,0.2); }
.accordion-header {
  width: 100%; padding: 20px 24px; display: flex; align-items: center;
  justify-content: space-between; background: var(--card-bg);
  border: none; cursor: pointer; font-family: inherit;
  color: var(--text-white); font-size: 1rem; font-weight: 600;
  transition: var(--transition);
}
.accordion-header:hover { background: rgba(27, 40, 56, 0.8); }
.accordion-chevron {
  width: 24px; height: 24px; transition: transform 0.3s ease;
  color: var(--accent-blue);
}
.accordion-item.active .accordion-chevron { transform: rotate(180deg); }
.accordion-body {
  max-height: 0; overflow: hidden; transition: max-height 0.4s ease;
  background: rgba(13, 27, 42, 0.5);
}
.accordion-item.active .accordion-body { max-height: 300px; }
.accordion-body-inner { padding: 0 24px 20px; color: var(--text-light); font-size: 0.95rem; line-height: 1.7; }

/* ========== STATS (Circular Indicators) ========== */
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; text-align: center; }
.stat-item { display: flex; flex-direction: column; align-items: center; }
.stat-circle {
  width: 160px; height: 160px; border-radius: 50%; position: relative;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
}
.stat-circle svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.stat-circle circle {
  fill: none; stroke-width: 4; cx: 80; cy: 80; r: 72;
}
.stat-circle .track { stroke: rgba(255,255,255,0.06); }
.stat-circle .fill { stroke: var(--accent-blue); stroke-linecap: round;
  stroke-dasharray: 452; stroke-dashoffset: 452;
  transition: stroke-dashoffset 1.5s ease;
}
.stat-value { font-size: 2.5rem; font-weight: 800; color: var(--text-white); z-index: 1; }
.stat-label { font-size: 0.95rem; color: var(--text-muted); max-width: 200px; }

/* ========== TIMELINE ========== */
.timeline { display: flex; flex-direction: column; gap: 32px; }
.timeline-item { display: flex; gap: 24px; align-items: flex-start; }
.timeline-marker {
  min-width: 80px; text-align: center;
}
.timeline-marker .time-val {
  font-size: 1.5rem; font-weight: 800; color: var(--accent-blue);
}
.timeline-marker .time-unit {
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--text-muted);
}
.timeline-content { flex: 1; }
.timeline-content h4 { font-size: 1rem; font-weight: 600; color: var(--text-white); margin-bottom: 8px; }
.timeline-content p { font-size: 0.9rem; color: var(--text-muted); margin-bottom: 12px; }
.progress-bar {
  height: 6px; background: rgba(255,255,255,0.06); border-radius: 3px; overflow: hidden;
}
.progress-fill {
  height: 100%; border-radius: 3px;
  background: linear-gradient(90deg, var(--accent-blue), var(--accent-green));
  transition: width 1.5s ease;
}

/* ========== TESTIMONIALS ========== */
.testimonials-carousel { position: relative; overflow: hidden; }
.testimonials-track {
  display: flex; transition: transform 0.5s ease;
}
.testimonial-card {
  min-width: 100%; padding: 0 12px;
}
.testimonial-inner {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: 12px; padding: 40px; text-align: center;
}
.testimonial-inner .quote {
  font-size: 1.15rem; color: var(--text-light); font-style: italic;
  line-height: 1.8; margin-bottom: 24px; max-width: 600px; margin-left: auto; margin-right: auto;
}
.testimonial-inner .quote::before { content: '\201C'; font-size: 3rem; color: var(--accent-blue);
  display: block; margin-bottom: -12px; line-height: 1; }
.testimonial-inner .author { font-size: 0.9rem; font-weight: 600; color: var(--accent-blue); }
.carousel-dots {
  display: flex; justify-content: center; gap: 10px; margin-top: 24px;
}
.carousel-dot {
  width: 10px; height: 10px; border-radius: 50%;
  background: rgba(255,255,255,0.15); border: none; cursor: pointer;
  transition: var(--transition);
}
.carousel-dot.active { background: var(--accent-blue); transform: scale(1.2); }

/* ========== PLATFORM DIAGRAM ========== */
.diagram-container {
  display: flex; align-items: center; justify-content: center;
  gap: 0; flex-wrap: wrap; padding: 40px 0;
}
.diagram-pillar {
  text-align: center; padding: 32px 28px; position: relative;
  flex: 1; min-width: 220px;
}
.diagram-pillar-icon {
  width: 72px; height: 72px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 16px; font-size: 1.8rem;
  box-shadow: 0 0 40px rgba(0,180,216,0.2);
}
.diagram-pillar h3 { font-size: 1rem; font-weight: 600; color: var(--text-white); margin-bottom: 8px; }
.diagram-pillar p { font-size: 0.85rem; color: var(--text-muted); }
.diagram-connector {
  width: 60px; height: 2px; background: linear-gradient(90deg, var(--accent-blue), var(--deep-blue));
  position: relative;
}
.diagram-connector::after {
  content: ''; position: absolute; right: -4px; top: -3px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--accent-blue);
}
.diagram-connector::before {
  content: ''; position: absolute; left: -4px; top: -3px;
  width: 8px; height: 8px; border-radius: 50%; background: var(--deep-blue);
}

/* ========== DATA LIFECYCLE DIAGRAM ========== */
.lifecycle-diagram {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: 16px; overflow: hidden; position: relative;
}
.lifecycle-step {
  padding: 40px 24px; text-align: center; position: relative;
  border-right: 1px solid var(--border-color);
}
.lifecycle-step:last-child { border-right: none; }
.lifecycle-step-num {
  width: 40px; height: 40px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  display: flex; align-items: center; justify-content: center;
  font-size: 0.9rem; font-weight: 700; color: #fff;
  margin: 0 auto 16px;
}
.lifecycle-step h4 { font-size: 0.95rem; font-weight: 600; color: var(--text-white); margin-bottom: 8px; }
.lifecycle-step p { font-size: 0.8rem; color: var(--text-muted); line-height: 1.5; }
.lifecycle-arrow {
  position: absolute; right: -12px; top: 50%; transform: translateY(-50%);
  z-index: 2; width: 24px; height: 24px; background: var(--primary-navy);
  border-radius: 50%; display: flex; align-items: center; justify-content: center;
  color: var(--accent-blue); font-size: 0.8rem; border: 2px solid var(--accent-blue);
}

/* ========== FORM ========== */
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.form-group { display: flex; flex-direction: column; }
.form-group.full-width { grid-column: 1 / -1; }
.form-group label {
  font-size: 0.85rem; font-weight: 500; color: var(--text-light);
  margin-bottom: 6px;
}
.form-group label .required { color: var(--accent-blue); }
.form-group input, .form-group select, .form-group textarea {
  background: rgba(255,255,255,0.05); border: 1px solid var(--border-color);
  border-radius: 8px; padding: 12px 16px; color: var(--text-white);
  font-family: inherit; font-size: 0.9rem; transition: var(--transition);
  outline: none;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  border-color: var(--accent-blue); box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}
.form-group input::placeholder, .form-group textarea::placeholder { color: var(--text-muted); }
.form-group textarea { resize: vertical; min-height: 100px; }
.form-group .error-msg { color: #FF6B6B; font-size: 0.8rem; margin-top: 4px; display: none; }
.form-group.has-error input, .form-group.has-error select { border-color: #FF6B6B; }
.form-group.has-error .error-msg { display: block; }

.btn-submit {
  background: linear-gradient(135deg, var(--accent-blue), var(--deep-blue));
  color: #fff; padding: 16px 48px; border-radius: 8px;
  font-size: 1rem; font-weight: 600; border: none; cursor: pointer;
  transition: var(--transition); width: 100%; margin-top: 12px;
}
.btn-submit:hover { transform: translateY(-2px); box-shadow: 0 12px 32px rgba(0,180,216,0.3); }

/* ========== SECURITY ========== */
.security-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.security-card { padding: 28px; }
.security-card .card-icon { background: linear-gradient(135deg, rgba(108,194,74,0.15), rgba(0,180,216,0.15)); }

/* ========== BENEFITS ========== */
.benefits-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px; }
.benefit-card { text-align: center; padding: 40px 24px; }
.benefit-icon {
  width: 64px; height: 64px; border-radius: 16px;
  background: linear-gradient(135deg, rgba(0,180,216,0.1), rgba(0,119,182,0.1));
  display: flex; align-items: center; justify-content: center;
  margin: 0 auto 20px; font-size: 1.6rem;
}

/* ========== ETL BENEFITS ========== */
.etl-benefits { display: grid; grid-template-columns: repeat(2, 1fr); gap: 20px; }
.etl-item {
  display: flex; align-items: flex-start; gap: 16px;
  padding: 24px; background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: 10px; transition: var(--transition);
}
.etl-item:hover { border-color: rgba(0,180,216,0.3); }
.etl-check {
  min-width: 28px; height: 28px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-green), var(--accent-blue));
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 0.8rem; font-weight: 700;
}
.etl-item h4 { font-size: 0.95rem; font-weight: 600; color: var(--text-white); margin-bottom: 6px; }
.etl-item p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.5; }

/* ========== CULTURE / CTA SECTIONS ========== */
.cta-section {
  padding: 80px 0; text-align: center;
}
.cta-section .section-title { max-width: 600px; margin: 0 auto 16px; }
.cta-section .section-desc { margin: 0 auto 32px; text-align: center; }

.split-cta {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px;
}
.split-cta-card {
  background: var(--card-bg); border: 1px solid var(--border-color);
  border-radius: 16px; padding: 48px; transition: var(--transition);
}
.split-cta-card:hover { border-color: rgba(0,180,216,0.3); }
.split-cta-card h3 { font-size: 1.3rem; font-weight: 700; color: var(--text-white); margin-bottom: 16px; }
.split-cta-card p { font-size: 0.95rem; color: var(--text-muted); margin-bottom: 24px; line-height: 1.7; }

/* ========== FOOTER ========== */
.footer {
  background: #080F1A; border-top: 1px solid var(--border-color);
  padding: 64px 0 32px;
}
.footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 40px; margin-bottom: 48px; }
.footer-brand p { color: var(--text-muted); font-size: 0.9rem; margin-top: 12px; line-height: 1.6; max-width: 280px; }
.footer-col h4 {
  color: var(--text-white); font-size: 0.85rem; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 16px;
}
.footer-col a { display: block; color: var(--text-muted); font-size: 0.875rem; padding: 4px 0; }
.footer-col a:hover { color: var(--accent-blue); }
.footer-bottom {
  border-top: 1px solid var(--border-color); padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 0.8rem; color: var(--text-muted); flex-wrap: wrap; gap: 16px;
}
.footer-login { display: flex; gap: 16px; }
.footer-login a { font-size: 0.8rem; }

/* ========== COOKIE BANNER ========== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 9999;
  background: var(--secondary-navy); border-top: 1px solid var(--border-color);
  padding: 20px 24px;
  transform: translateY(0); transition: transform 0.4s ease;
  box-shadow: 0 -8px 32px rgba(0,0,0,0.3);
}
.cookie-banner.hidden { transform: translateY(100%); pointer-events: none; }
.cookie-inner {
  max-width: 1200px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  gap: 24px; flex-wrap: wrap;
}
.cookie-inner p { font-size: 0.875rem; color: var(--text-light); flex: 1; }
.cookie-btns { display: flex; gap: 12px; }
.cookie-accept {
  background: var(--accent-blue); color: #fff; padding: 8px 20px;
  border-radius: 6px; border: none; font-size: 0.85rem; font-weight: 600;
  cursor: pointer; transition: var(--transition);
}
.cookie-accept:hover { background: var(--deep-blue); }
.cookie-decline {
  background: transparent; color: var(--text-muted); padding: 8px 20px;
  border-radius: 6px; border: 1px solid var(--border-color);
  font-size: 0.85rem; font-weight: 500; cursor: pointer; transition: var(--transition);
}
.cookie-decline:hover { border-color: var(--text-muted); color: var(--text-light); }

/* ========== FORM SUCCESS ========== */
.form-success {
  text-align: center; padding: 48px; display: none;
}
.form-success.active { display: block; }
.form-success .check-circle {
  width: 80px; height: 80px; border-radius: 50%;
  background: linear-gradient(135deg, var(--accent-green), var(--accent-blue));
